        days = (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
        months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
        for i in range(m - 1):
